   </style>
 </head>
 <body>
   <main class="app" id="app"></main>

   <script>
     const faqs = [
       {
         question: "Why do cats purr?",
         answer:
           "Cats often purr when they feel safe and content, but they may also purr to comfort themselves or communicate during stressful moments."
       },
       {
         question: "How much sleep do cats need?",
         answer:
           "Most cats sleep between 12 and 16 hours a day, and kittens or senior cats can sleep even more."
       },
       {
         question: "Why do cats knead with their paws?",
         answer:
           "Kneading is a comforting behavior that starts in kittenhood. Adult cats often do it when they are relaxed, happy, or bonding with a person."
       },
       {
         question: "Do indoor cats need enrichment?",
         answer:
           "Yes. Scratching posts, climbing spaces, puzzle feeders, and interactive play help keep indoor cats healthy and mentally engaged."
       }
     ];

     function FAQItem({ question, answer }, index) {
       return `
         <div class="example" aria-expanded="false" data-faq-item>
           <button class="question" type="button" aria-expanded="false" aria-controls="faq-answer-${index}" id="faq-question-${index}">
             <span class="question-text">${question}</span>
             <span class="chevron" aria-hidden="true">⌄</span>
           </button>
           <div class="details" id="faq-answer-${index}" role="region" aria-labelledby="faq-question-${index}">
             <p>${answer}</p>
           </div>
         </div>
       `;
     }

     function App() {
       return `
         <header>
           <p class="eyebrow">FAQ</p>
           <h1>Cat questions, answered</h1>
           <p class="intro">A compact, polished FAQ with answers hidden by default and revealed one at a time.</p>
         </header>
         <section class="faq-list" aria-label="Frequently asked questions about cats">
           ${faqs.map(FAQItem).join("")}
         </section>
       `;
     }

     document.getElementById("app").innerHTML = App();

     document.querySelectorAll("[data-faq-item]").forEach((item) => {
       const button = item.querySelector(".question");
       button.addEventListener("click", () => {
         const expanded = button.getAttribute("aria-expanded") === "true";
         button.setAttribute("aria-expanded", String(!expanded));
         item.setAttribute("aria-expanded", String(!expanded));
       });
     });
   </script>
 </body>
 </html>

